// Config — edit these variables
const GITHUB_REPO = $env.GITHUB_REPO || 'owner/repo';
const DAYS_BACK = 7;
const now = new Date();
const since = new Date(now.getTime() - DAYS_BACK * 24 * 60 * 60 * 1000).toISOString();

return [{
  json: {
    repo: GITHUB_REPO,
    since,
    now: now.toISOString()
  }
}];

const since = new Date($('Set Config').item.json.since);
const repo = $('Set Config').item.json.repo;
const lang = $env.SUMMARY_LANGUAGE || 'EN';

// Commits from fetch-commits node
const commitsRaw = $('Fetch Commits').all();
const commits = commitsRaw
  .map(i => i.json)
  .filter(c => c.commit)
  .map(c => `- ${c.commit.message.split('\n')[0]} (${c.sha.slice(0,7)})`);

// Issues from fetch-issues
const issuesRaw = $('Fetch Closed Issues').all();
const issues = issuesRaw
  .map(i => i.json)
  .filter(i => i.closed_at && new Date(i.closed_at) > since && !i.pull_request)
  .map(i => `- #${i.number}: ${i.title}`);

// PRs from fetch-prs
const prsRaw = $('Fetch Merged PRs').all();
const prs = prsRaw
  .map(i => i.json)
  .filter(p => p.merged_at && new Date(p.merged_at) > since)
  .map(p => `- PR #${p.number}: ${p.title} (@${p.user?.login || 'unknown'})`);

const langInstruction = lang === 'FR'
  ? 'Respond entirely in French.'
  : 'Respond in English.';

const prompt = `You are writing a weekly engineering summary for the GitHub repository "${repo}".
${langInstruction}

Here is the raw activity from the past 7 days:

## Commits (${commits.length})
${commits.slice(0, 30).join('\n') || '(none)'}

## Closed Issues (${issues.length})
${issues.slice(0, 20).join('\n') || '(none)'}

## Merged PRs (${prs.length})
${prs.slice(0, 20).join('\n') || '(none)'}

Write a concise, engaging narrative summary (300–500 words) suitable for a team newsletter or Slack update. Highlight the most impactful changes, note any themes, and end with what to watch next week. Do not reproduce the raw lists — synthesize them into prose.`;

return [{ json: { prompt, repo, commits_count: commits.length, issues_count: issues.length, prs_count: prs.length } }];

const claudeResponse = $json;
const summary = claudeResponse.content?.[0]?.text || 'No summary generated.';
const repo = $('Build Claude Prompt').item.json.repo;
const now = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

const stats = $('Build Claude Prompt').item.json;

const slackMessage = {
  text: `📊 *Weekly Dev Summary — ${repo}* (${now})`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `Weekly Dev Summary — ${repo}` }
    },
    {
      type: 'context',
      elements: [{ type: 'mrkdwn', text: `${now} · ${stats.commits_count} commits · ${stats.prs_count} PRs · ${stats.issues_count} issues closed` }]
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: summary }
    }
  ]
};

return [{ json: slackMessage }];
